LEGACY_RECORDS = [{'source': '', 'values': {'ProductName': 'Spinach', 'marketing_campaign_format': 'Brochure', 'Weight': '230', 'supplier_contact_channel': 'Email', 'packaging_label_review_count': '3', 'supplier_catalog_revision_count': '3', 'supplier_quality_rating': '3.2', 'Value': '64', 'catalog_display_group': 'Featured'}}, {'source': '', 'values': {'ProductName': 'Shiitake Mushrooms', 'marketing_campaign_format': 'Brochure', 'Weight': '637', 'supplier_contact_channel': 'Portal', 'packaging_label_review_count': '5', 'supplier_catalog_revision_count': '3', 'supplier_quality_rating': '4.1', 'Value': '75', 'catalog_display_group': 'Featured'}}, {'source': '', 'values': {'ProductName': 'Apples', 'marketing_campaign_format': 'Brochure', 'Weight': '773', 'supplier_contact_channel': 'Email', 'packaging_label_review_count': '3', 'supplier_catalog_revision_count': '1', 'supplier_quality_rating': '4.7', 'Value': '68', 'catalog_display_group': 'Seasonal'}}, {'source': '', 'values': {'ProductName': 'Carrots', 'marketing_campaign_format': 'Brochure', 'Weight': '653', 'supplier_contact_channel': 'Portal', 'packaging_label_review_count': '2', 'supplier_catalog_revision_count': '3', 'supplier_quality_rating': '4.7', 'Value': '11', 'catalog_display_group': 'Featured'}}, {'source': '', 'values': {'ProductName': 'Basil', 'marketing_campaign_format': 'Web feature', 'Weight': '755', 'supplier_contact_channel': 'Email', 'packaging_label_review_count': '3', 'supplier_catalog_revision_count': '6', 'supplier_quality_rating': '4.1', 'Value': '91', 'catalog_display_group': 'Seasonal'}}, {'source': '', 'values': {'ProductName': 'Potatoes', 'marketing_campaign_format': 'Brochure', 'Weight': '670', 'supplier_contact_channel': 'Portal', 'packaging_label_review_count': '3', 'supplier_catalog_revision_count': '6', 'supplier_quality_rating': '3.5', 'Value': '31', 'catalog_display_group': 'Everyday'}}, {'source': '', 'values': {'ProductName': 'Green Beans', 'marketing_campaign_format': 'Brochure', 'Weight': '505', 'supplier_contact_channel': 'Phone', 'packaging_label_review_count': '9', 'supplier_catalog_revision_count': '1', 'supplier_quality_rating': '4.1', 'Value': '90', 'catalog_display_group': 'Featured'}}, {'source': '', 'values': {'ProductName': 'Blueberries', 'marketing_campaign_format': 'Brochure', 'Weight': '821', 'supplier_contact_channel': 'Portal', 'packaging_label_review_count': '5', 'supplier_catalog_revision_count': '6', 'supplier_quality_rating': '3.5', 'Value': '56', 'catalog_display_group': 'Seasonal'}}, {'source': '', 'values': {'ProductName': 'Oranges', 'marketing_campaign_format': 'Web feature', 'Weight': '83', 'supplier_contact_channel': 'Phone', 'packaging_label_review_count': '3', 'supplier_catalog_revision_count': '4', 'supplier_quality_rating': '3.2', 'Value': '10', 'catalog_display_group': 'Seasonal'}}, {'source': '', 'values': {'ProductName': 'Watermelons', 'marketing_campaign_format': 'Web feature', 'Weight': '249', 'supplier_contact_channel': 'Email', 'packaging_label_review_count': '7', 'supplier_catalog_revision_count': '3', 'supplier_quality_rating': '4.4', 'Value': '24', 'catalog_display_group': 'Everyday'}}, {'source': '', 'values': {'refrigeration_service_visits': '8', 'Capacity': '875', 'storage_sanitation_inspections_last_year': '6'}}]
import gurobipy as gp
from gurobipy import GRB
records = LEGACY_RECORDS
product_records = [r for r in records if 'ProductName' in r['values']]
if len(product_records) == 0:
    raise ValueError('No product records found in LEGACY_RECORDS.')
capacity_records = [r for r in records if 'Capacity' in r['values']]
if len(capacity_records) == 0:
    raise ValueError('No capacity record found in LEGACY_RECORDS.')
if len(capacity_records) > 1:
    raise ValueError('Multiple capacity records found in LEGACY_RECORDS.')
products = []
values = {}
weights = {}
for rec in product_records:
    pname = rec['values']['ProductName']
    products.append(pname)
    try:
        values[pname] = int(rec['values']['Value'])
        weights[pname] = int(rec['values']['Weight'])
    except Exception as e:
        raise ValueError(f'Missing or invalid Value/Weight for product {pname}: {e}')
try:
    total_capacity = int(capacity_records[0]['values']['Capacity'])
except Exception as e:
    raise ValueError(f'Missing or invalid Capacity: {e}')
if len(products) != len(values) or len(products) != len(weights):
    raise ValueError('Mismatch in product, value, or weight dimensions.')
m = gp.Model('SupermarketStock')
x = m.addVars(products, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((values[p] * x[p] for p in products)), GRB.MAXIMIZE)
m.addConstr(gp.quicksum((weights[p] * x[p] for p in products)) <= total_capacity, name='capacity')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')